(4, '2014 Ford Focus', '2014-ford-focus', 'Used', 'Dark Grey', 'Black ', 'Ford', 'Manual', 'N/A', '4 Door', 'FWD', '4', 'Fuel', 'N/A', '&nbsp;\r\n\r\nSelling 2014 Ford Focus SE with 158000 kms in immaculate condition it’s a 6 speed manual transmission super cheap in gas and drives excellent, this car would be sold fully certified, great for Uber and daily driving.<span class=\"Apple-converted-space\"> </span>\r\n<br/><br/>\r\n<div>\r\n<p>For any inquiries please contact one of our sales agents</p>\r\n\r\n<p>Sales-persons:</p>\r\nAshraf Alighazi<br/>\r\nTel: <a href=\"tel:6475217186\">647-521-7186</a><br/>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\">xtremeinc.86@gmail.com</a><br/><br/>\r\n\r\nOmar Alighazi<br/>\r\nTel: <a href=\"tel:6475456393\">647-545-6393</a><br/>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\">xtremeinc.86@gmail.com</a>\r\n</div>', 'sold', 158000, 'km', 4999, 'N/A', '5', '[\" Bluetooth\", \" Bluetooth Audio\"]', 2014, '[\"/storage/car/97/original/5797.jpg\", \"/storage/car/98/original/5798.jpg\", \"/storage/car/99/original/5799.jpg\", \"/storage/car/00/original/5800.jpg\", \"/storage/car/01/original/5801.jpg\", \"/storage/car/02/original/5802.jpg\", \"/storage/car/03/original/5803.jpg\", \"/storage/car/04/original/5804.jpg\", \"/storage/car/05/original/5805.jpg\", \"/storage/car/06/original/5806.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:27', '2024-01-15 03:02:27', NULL, NULL, NULL, NULL, NULL),
