(6, '2007 infinity G35 AWD', '2007-infinity-g35-awd', 'Used', 'Blue', 'Blakc ', 'Infiniti', 'Automatic', 'G35', '4 Door', 'AWD', '4', 'Fuel', 'N/A', '<p style=\"text-align: left;\">2007 infinity G35 All wheel drive , great condition, no accident history , comes with two months dealer warranty, and optional two years or unlimited km warranty for only $799, it has navigation, back up camera , heated seats, sunroof, leather seats, Bluetooth and much more.</p>\r\nthis car has 4 brand new brakes in the front and in the bank and would be sold fully certified.\r\n\r\n<br/><br/>\r\n<div>\r\n<p>For any inquiries please contact one of our sales agents</p>\r\n\r\n<p>Sales-persons:</p>\r\nAshraf Alighazi<br/>\r\nTel: <a href=\"tel:6475217186\">647-521-7186</a><br/>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\">xtremeinc.86@gmail.com</a><br/><br/>\r\n\r\nOmar Alighazi<br/>\r\nTel: <a href=\"tel:6475456393\">647-545-6393</a><br/>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\">xtremeinc.86@gmail.com</a>\r\n</div>', 'sold', 245000, 'km', 2999, 'N/A', '5 ', '[\" Active Curise Control\", \" AWD\", \" Fully Loaded\", \" Leather seats\", \" LED Headlight\", \" navigation system\", \" Paddle Shift\", \" Panoramic Sunroof\", \" Power Seats\", \" Power Tailgate\", \" Rearview Camera\", \" Sunroof\"]', 2007, '[\"/storage/car/19/original/5819.jpg\", \"/storage/car/20/original/5820.jpg\", \"/storage/car/21/original/5821.jpg\", \"/storage/car/22/original/5822.jpg\", \"/storage/car/23/original/5823.jpg\", \"/storage/car/24/original/5824.jpg\", \"/storage/car/25/original/5825.jpg\", \"/storage/car/26/original/5826.jpg\", \"/storage/car/27/original/5827.jpg\", \"/storage/car/28/original/5828.jpg\", \"/storage/car/29/original/5829.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:27', '2024-01-15 03:02:27', NULL, NULL, NULL, NULL, NULL),
