(22, '2012 BMW 335i M PERFORMANCE', '2012-bmw-335i-m-performance', 'Used', 'Brown', 'beige', 'BMW', '8 Speed Automatic', '335i', 'Sedan', 'RWD', '4', 'GAS', 'N/A', 'Finance available for any type of credit\r\nSelling 2012 BMW 335I M Sport package twin-turbo 303 horsepower 3.3L V6 engine that runs and drives excellent has absolutely not a single issue has Low KMS of 72000 and has every single premium options that come available in a BMW\r\nThis car is truly a price of Gem. No accident history at all. Optional two years and unlimited km power terrain warranty. That covers up to $5000 per claim.\r\n<br/><br/>\r\n<div>\r\n<p>For any inquiries please contact one of our sales agents</p>\r\n\r\n<p>Sales-persons:</p>\r\nAshraf Alighazi<br/>\r\nTel: <a href=\"tel:6475217186\">647-521-7186</a><br/>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\">xtremeinc.86@gmail.com</a><br/><br/>\r\n\r\nOmar Alighazi<br/>\r\nTel: <a href=\"tel:6475456393\">647-545-6393</a><br/>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\">xtremeinc.86@gmail.com</a>\r\n</div>', 'sold', 72000, 'km', 16999, '3.3L', '5', '[\" Active Curise Control\", \" Advance Key\", \" Bluetooth\", \" Bluetooth Audio\", \" Bose Sound\", \" Comfort Seat\", \" Dynamic Seat\", \" Fully Loaded\", \" Keyless Go\", \" Lane Keep Assist\", \" Leather seats\", \" LED Headlight\", \" M-Sport Pkg\", \" Multi-Function Steering Wheel\", \" navigation system\", \" Paddle Shift\", \" Panoramic Sunroof\", \" parking sensors\", \" Power Folding Mirror\", \" Power Seat with Memories\", \" Power Seats\", \" Power Tailgate\", \" Rearview Camera\", \" Sport Seat\", \" Sunroof\", \" traction control\"]', 2012, '[\"/storage/car/28/original/6128.jpg\", \"/storage/car/29/original/6129.jpg\", \"/storage/car/30/original/6130.jpg\", \"/storage/car/31/original/6131.jpg\", \"/storage/car/32/original/6132.jpg\", \"/storage/car/33/original/6133.jpg\", \"/storage/car/34/original/6134.jpg\", \"/storage/car/35/original/6135.jpg\"]', 0, 0, 1, NULL, '