(26, '2006 LEXUS IS250 FULLY LOADED', '2006-lexus-is250-fully-loaded', 'Used', 'Silver', 'black', 'Lexus ', 'Automatic', 'Is250', 'Sedan', 'RWD', '4', 'GAS', 'N/A', 'Selling Lexus is250 fully loaded with leather seats, heated seats/cooling seats, navigation, sunroof, Bluetooth and much more. runs and drives excellent have absolutely not a single issue, has 164000 KMS and has every single premium option that comes available in a Lexus. This car is truly a price of Gem. Optional two years and unlimited km power terrain warranty. That covers up to $5000 per claim.\r\n\r\nFor any inquiries please contact one of our sales agents\r\n\r\nSales-persons:\r\n\r\nAshraf Alighazi\r\nTel: 647-521-7186\r\nEmail: xtremeinc.86@gmail.com\r\n\r\nOmar Alighazi\r\nTel: 647-545-6393\r\nEmail: xtremeinc.86@gmail.com', 'sold', 164000, 'km', 6999, '2.5L', '5', '[\" Active Curise Control\", \" air Cond. Seats\", \" Bluetooth\", \" Bluetooth Audio\", \" Bose Sound\", \" Fully Loaded\", \" Keyless Entry\", \" Keyless Go\", \" Leather seats\", \" LED Headlight\", \" Multi-Function Steering Wheel\", \" navigation system\", \" Paddle Shift\", \" Power Folding Mirror\", \" Power Seats\", \" Rearview Camera\", \" Sunroof\", \" traction control\"]', 2006, '[\"/storage/car/85/original/8785.jpg\", \"/storage/car/86/original/8786.jpg\", \"/storage/car/87/original/8787.jpg\", \"/storage/car/88/original/8788.jpg\", \"/storage/car/89/original/8789.jpg\", \"/storage/car/90/original/8790.jpg\", \"/storage/car/91/original/8791.jpg\", \"/storage/car/92/original/8792.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:31', '2024-01-15 03:02:31', NULL, NULL, NULL, NULL, NULL),
