(136, '2014 TOYOTA SIENNA LE', '2014-toyota-sienna-le', 'Used', 'Dark Green', 'beige', 'Toyota', 'Automatic', 'N/A', 'Minivan', 'FWD', '4', 'GAS', 'LE', 'Financing available 2014 Toyota Sienna LE in immaculate condition with 148000 km and equipped with Bluetooth, backup camera, handsfree and more. Optional two years and unlimited km power terrain warranty. That covers up to $5000 per claim.\r\n\r\n&nbsp;\r\n<div>\r\n<p data-ss-id=\"rwTH4d70c2f2418d8f5d0d34d1e7d8d15650\">For any inquiries please contact one of our sales agents</p>\r\n<p data-ss-id=\"rwTHe5622b9488161be4a8329933b5666414\">Sales-persons:</p>\r\nAshraf Alighazi\r\nTel: <a href=\"tel:6475217186\" data-ss-id=\"rwTH9a65d4df91a62eb42754ea1192b8d8f0\">647-521-7186</a>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\" data-ss-id=\"rwTHebaaba1e0c23e068f560a0032df15e07\">xtremeinc.86@gmail.com</a>\r\n\r\nOmar Alighazi\r\nTel: <a href=\"tel:6475456393\" data-ss-id=\"rwTH4d8780cf2ec808576fb0b29f9e650d74\">647-545-6393</a>\r\nEmail: <a href=\"mailto:xtremeinc.86@gmail.com\" data-ss-id=\"rwTHebaaba1e0c23e068f560a0032df15e071\">xtremeinc.86@gmail.com</a>\r\n\r\n</div>', 'sold', 149000, 'km', 17500, '3.6L', '8', '[\" Active Curise Control\", \" Bluetooth\", \" Bluetooth Audio\", \" Bose Sound\", \" Comfort Seat\", \" Multi-Function Steering Wheel\", \" Power Seats\", \" Rearview Camera\", \" Towing Package\", \" traction control\"]', 2014, '[\"/storage/car/28/original/9928.jpg\", \"/storage/car/29/original/9929.jpg\", \"/storage/car/30/original/9930.jpg\", \"/storage/car/31/original/9931.jpg\", \"/storage/car/32/original/9932.jpg\", \"/storage/car/33/original/9933.jpg\", \"/storage/car/34/original/9934.jpg\", \"/storage/car/35/original/9935.jpg\", \"/storage/car/36/original/9936.jpg\", \"/storage/car/37/original/9937.jpg\", \"/storage/car/38/original/9938.jpg\", \"/storage/car/39/original/9939.jpg\", \"/storage/car/40/original/9940.jpg\", \"/storage/car/41/original/9941.jpg\", \"/storage/car/42/original/9942.jpg\", \"/storage/car/43/original/9943.jpg\", \"/storage/car/44/original/9944.jpg\", \"/storage/car/45/original/9945.jpg\", \"/storage/car/46/original/9946.jpg\", \"/storage/car/47/original/9947.jpg\", \"/storage/car/48/original/9948.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:52', '2024-01-15 03:02:52', NULL, NULL, NULL, NULL, NULL),
(137, '2011 BMW 335I XDRIVE', '2011-bmw-335i-xdrive', 'Used', 'Black', 'brown', 'BMW', 'Automatic', '335i', 'Sedan', 'AWD', '4', 'GAS', 'premium', '<p>The BMW 335i xDrive is a machine built for those who crave precision and power in every drive.</p><p> It carries the unmistakable DNA of BMW, blending performance with refined luxury.</p><p> Under the hood lies a turbocharged inline-6 engine that delivers thrilling acceleration without hesitation.</p><p> The xDrive all-wheel-drive system ensures confidence in every condition, from dry pavement to snow-covered roads.</p><p> Its steering is razor-sharp, giving the driver a direct connection to the road.</p><p> The balance between comfort and sportiness is masterfully engineered.</p><p> Every curve feels intentional, every straightaway an invitation to push further.</p><p> The cabin surrounds you with premium materials and a driver-focused design.</p><p> Technology is intuitive, enhancing the experience without overwhelming it.</p><p> Acceleration is smooth yet aggressive, offering both control and excitement.</p><p> The exhaust note delivers a deep, satisfying growl that hints at its true capability.</p><p> This car doesn’t just move—it responds.</p><p> It anticipates driver input with precision and composure.</p><p> Even at high speeds, it remains stable and composed.</p><p> The braking system inspires confidence with strong and consistent stopping power.</p><p> Its design is timeless, with a sporty silhouette that still turns heads.</p><p> Driving it feels less like transportation and more like an experience.</p><p> It embodies a perfect blend of engineering and emotion.</p><p> Every journey becomes engaging, no matter the distance.</p><p> The 2011 BMW 335i xDrive is not just a car—it’s a statement of performance, control, and driving passion</p><p><br></p><p>\n</p><p><br></p><p>\n</p><p><br></p><p>\n</p><p><br></p>', 'available', 146800, 'km', 12999, '3.0L TWIN TURBO', '5', '[\"Active Curise Control\",\"AWD\",\"Bluetooth\",\"Fully Loaded\",\"Harman Kardon Sound\",\"Leather seats\",\"LED Headlight\",\"Multi-Function Steering Wheel\",\"Paddle Shift\",\"parking sensors\",\"Power Seats\",\"Sport Seat\",\"Sunroof\",\"traction control\"]', 2011, '[\"/storage/car/49/original/9949.jpg\", \"/storage/car/50/original/9950.jpg\", \"/storage/car/51/original/9951.jpg\", \"/storage/car/52/original/9952.jpg\", \"/storage/car/53/original/9953.jpg\", \"/storage/car/54/original/9954.jpg\", \"/storage/car/55/original/9955.jpg\", \"/storage/car/56/original/9956.jpg\", \"/storage/car/57/original/9957.jpg\", \"/storage/car/58/original/9958.jpg\", \"/storage/car/59/original/9959.jpg\", \"/storage/car/60/original/9960.jpg\", \"/storage/car/61/original/9961.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:52', '2026-04-30 04:18:31', NULL, 'https://vhr.carfax.ca/?id=yfidlKm4Op6IOkdfqd7wOBKbezCcbu%2B5', 'WBAPOL5C52BA917123', '7.5', '6.1'),
(138, '2019 HONDA CIVIC TOURING', '2019-honda-civic-touring', 'Used', 'Dark Grey', 'black', 'Honda', 'Automatic', 'Civic', 'Sedan', 'FWD', '4', 'GAS', 'TOURING', '<div class=\"info_box\">\r\n<div class=\"car_info\">\r\n<div class=\"info_right\">\r\n<div class=\"first\">\r\n<div>\r\n<div class=\"first\">2019 Honda Civic Touring. Equipped with heated seats, Bluetooth, apple car play and much more. It runs and drives excellently, has absolutely no single issue, and has 23675 KMS. Optional two years and unlimited km power terrain warranty. That covers up to $5000 per claim.</div>\r\n<div></div>\r\n<div></div>\r\n<div class=\"first\" data-ss-id=\"rwTH627d4e6c48e07373bb186b5d1513ac9b\">For any inquiries, please get in touch with one of our Sales-persons:</div>\r\n</div>\r\n<div class=\"first\" data-ss-id=\"rwTHa0b061ee066bed4e00d9185d92ba94ff\">Ashraf Alighazi</div>\r\n<div class=\"first\">Tel: 647-521-7186</div>\r\n<div class=\"first\">Email: xtremeinc.86@gmail.com</div>\r\n<div></div>\r\n<div></div>\r\n<div class=\"first\" data-ss-id=\"rwTH40d0dc2c3bc2199acde6a699afbb3b7e\">Omar Alighazi</div>\r\n<div class=\"first\">Tel: 647-545-6393</div>\r\n<div class=\"first\">Email: xtremeinc.86@gmail.com</div>\r\n<div></div>\r\n<div></div>\r\n<div data-ss-id=\"rwTHb7bf05e7a34051fc25c920f29c2a03ac\">Emad Alighazi</div>\r\n<div>Tel: 647-573-2552</div>\r\n<div>Email: xtremeinc.86@gmail.com</div>\r\n</div>\r\n</div>\r\n<div class=\"clear\"></div>\r\n</div>\r\n</div>\r\n<div class=\"cars_id\"></div>', 'sold', 23650, 'km', 29500, '1.5L TURBO', '5', '[\" Active Curise Control\", \" Advance Key\", \" Blind Spot Assist\", \" Bluetooth\", \" Bluetooth Audio\", \" Bose Sound\", \" Dynamic Seat\", \" Fully Loaded\", \" Keyless Entry\", \" Keyless Go\", \" Lane Keep Assist\", \" Leather seats\", \" LED Headlight\", \" Multi-Function Steering Wheel\", \" navigation system\", \" Paddle Shift\", \" Power Folding Mirror\", \" Power Seats\", \" Rearview Camera\", \" Sunroof\", \" traction control\"