al/10336.jpg\", \"/storage/car/37/original/10337.jpg\", \"/storage/car/38/original/10338.jpg\", \"/storage/car/39/original/10339.jpg\", \"/storage/car/40/original/10340.jpg\", \"/storage/car/41/original/10341.jpg\", \"/storage/car/42/original/10342.jpg\", \"/storage/car/43/original/10343.jpg\", \"/storage/car/44/original/10344.jpg\", \"/storage/car/45/original/10345.jpg\", \"/storage/car/46/original/10346.jpg\", \"/storage/car/47/original/10347.jpg\", \"/storage/car/48/original/10348.jpg\", \"/storage/car/49/original/10349.jpg\", \"/storage/car/50/original/10350.jpg\", \"/storage/car/51/original/10351.jpg\", \"/storage/car/52/original/10352.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:57', '2024-01-15 03:02:57', NULL, NULL, NULL, NULL, NULL),
(160, '2010 TOYOTA FJ CRUISER', '2010-toyota-fj-cruiser', 'Used', 'Maroon', 'Black', 'Toyota', 'Automatic', 'FJ CRUISER', 'Suv', 'AWD', '4', 'GAS', 'LE', '<p>The 2010 Toyota FJ Cruiser is a rugged and iconic SUV designed for off-road enthusiasts. Under its bold and distinctive exterior, it is powered by a robust 4.0-liter V6 engine. This engine produces 260 horsepower and 271 lb-ft of torque, providing ample power for both on-road and off-road adventures.</p><p><br></p><p>Paired with a five-speed automatic transmission, the FJ Cruiser ensures a responsive and versatile driving experience. Its off-road capabilities are enhanced by features such as a part-time 4WD system, a locking rear differential, and a robust suspension system, making it well-suited for tackling various terrains with ease.</p><p><br></p><p>In addition to its impressive performance, the 2010 FJ Cruiser showcases a distinctive design, including its signature white roof, rear-hinged half-doors, and a boxy silhouette reminiscent of its iconic predecessor, the FJ40. With its combination of powerful performance and rugged design, the 2010 Toyota FJ Cruiser remains a standout choice for those seeking a capable and stylish off-road SUV.</p><p>\n</p><p>for inquires, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com\n</p>', 'sold', 77361, 'km', 25000, '4.0L', '5', '[\"Active Curise Control\", \"AWD\", \"Bose Sound\", \"Comfort Seat\", \"LED Headlight\", \"Multi-Function Steering Wheel\", \"Rearview Camera\", \"Towing Package\", \"traction control\", \"Traction control\", \"LED Headlight\", \"All Wheel Drive\", \"20\\\" Sport Wheels\", \"Rearview Camera\", \"Towing Package\", \"Active Curise Control\"]', 2010, '[\"\\/storage\\/car\\/53\\/original\\/10353.jpg\",\"\\/storage\\/car\\/54\\/original\\/10354.jpg\",\"\\/storage\\/car\\/55\\/original\\/10355.jpg\",\"\\/storage\\/car\\/56\\/original\\/10356.jpg\",\"\\/storage\\/car\\/57\\/original\\/10357.jpg\",\"\\/storage\\/car\\/58\\/original\\/10358.jpg\",\"\\/storage\\/car\\/59\\/original\\/10359.jpg\",\"\\/storage\\/car\\/62\\/original\\/10362.jpg\",\"\\/storage\\/car\\/63\\/original\\/10363.jpg\",\"\\/storage\\/car\\/65\\/original\\/10365.jpg\",\"\\/storage\\/car\\/66\\/original\\/10366.jpg\"]', 0, 0, 1, NULL, '2024-01-15 03:02:57', '2024-02-23 02:50:40', 'https://www.youtube.com/embed/3kr5HA4X_Uk?si=3k4D45jxULlVoUIa', NULL, NULL, NULL, NULL),
