(186, '2013 HONDA ACCORD EX-L', '2013-honda-accord-ex-l', 'Used', 'Black', 'Black', 'Honda', 'Automatic', 'Accord', 'Sedan', 'FWD', '4', 'GAS', 'TOURING', '<p>The 2013 Honda Accord EX-L is a sophisticated midsize sedan featuring a robust 2.4-liter i-VTEC engine, delivering 185 horsepower. Paired with a smooth CVT, it provides an efficient and comfortable driving experience. The EX-L trim adds luxury with leather upholstery, heated seats, and advanced tech features, making it an appealing choice for those seeking a stylish and well-equipped sedan.</p><p><br></p><p>for inquires, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 163000, 'km', 12786, '2.4L', '5', '[\"Traction control\", \"Navigation system\", \"Bluetooth\", \"Keyless Entry\", \"Power Seats\", \"Fully Loaded\", \"Leather seats\", \"Sunroof\", \"19\\\" Sport Wheels\", \"Bluetooth Audio\", \"Rearview Camera\", \"Upgraded Soft Leather\", \"Multi-Function Steering Wheel\", \"Dynamic Seat\", \"Blind Spot Assist\", \"Lane Keep Assist\", \"Power Seat with Memories\", \"Advance Key\", \"Keyless Go\", \"Bose Sound\", \"Active Curise Control\"]', 2013, '[\"/storage/images/xDlO5oEwlPDv6jF6urUd3GU0g2NQEKocE4YjHrUJ.jpg\", \"/storage/images/NMUAplYjDnOcztaDplEJxYApKy5TNG5PuM5ZCvNY.jpg\", \"/storage/images/VTOa1OaXMES8zYHA3mKW3zNnIPh3UCfOg27Dw0yr.jpg\", \"/storage/images/zYatD8saQtf1XA0NEdb96fEAhGARIrejeLwQT7vf.jpg\", \"/storage/images/9mlcSU3QaTevZcbemgfouvUeyEpKCOfNjeG1tkt2.jpg\", \"/storage/images/Ks52yrGWILf3Ie9aK52RrEP9sHDFxp1hbV1FEWbl.jpg\", \"/storage/images/8g4b08o9QkgG5sfThptce1ZtqH5JhVY53OOaqDop.jpg\", \"/storage/images/GwaS2V2PcrhKNztuaYHMckX1Er4qRnuNwAazMwWo.jpg\", \"/storage/images/jj2Eaw42C1U6MDYgW8JB6O7dwiqcHvi6bGZ2DrBL.jpg\", \"/storage/images/4eRnm7f2WwrZcfp7ZW4Z5hFB4OUji9jakWZ1MKll.jpg\", \"/storage/images/CyrYqABVHGgfVXAqCVP6A3IHAxPVO3AxaO6ZaUmc.jpg\", \"/storage/images/fJzQjoiECYJ48ZYfHdi3OGAnlcHgDsoYOH4DGW9h.jpg\", \"/storage/images/utqmXvBGzWgxK7YJSaQjW9DK0N4I7wlXuB1CcTV9.jpg\", \"/storage/images/C2y23dHqOu5kRjxyt72CpBi4nyNDokzirj34qXTc.jpg\", \"/storage/images/sfuTkFLyXWrjzEAaWReyKfnyjWMUtWdB8A0VzbpW.jpg\", \"/storage/images/XcdgvvNliYuURmX1Ik6rMTQHmRlCwaw5kQZb7ZoK.jpg\", \"/storage/images/CHKBnOv4gCnYoiOxkc7MJS9o9ZyT6t2MXS4Z39ac.jpg\", \"/storage/images/Ke9ilO4ZRJ7secHY7i0MvVbmwLWAPmkknRl4Kdaj.jpg\", \"/storage/images/KkaBMRJ496CcKrIv6tph1H1LMptzUNLMVt7i8HIH.jpg\"]', 0, 0, 1, NULL, '2024-01-24 04:59:11', '2024-02-23 02:50:09', NULL, NULL, NULL, NULL, NULL),
(187, '2015 HONDA ACCORD TOURING', '2015-honda-accord-touring', 'Used', 'Grey', 'Black', 'Honda', 'Automatic', 'Accord', 'Sedan', 'FWD', '4', 'GAS', 'TOURING', '<p>The 2015 Honda Accord Touring is a top-tier midsize sedan that seamlessly combines performance and sophistication. Under the hood, it boasts a powerful 3.5-liter V6 engine, generating 278 horsepower and 252 lb-ft of torque. Paired with a responsive 6-speed automatic transmission, the Accord Touring delivers a dynamic and engaging driving experience.</p><p><br></p><p>In terms of features, the Touring trim offers a premium driving environment with leather upholstery, heated front and rear seats, and a power-adjustable driver\'s seat. The advanced technology suite includes a navigation system, premium audio, and Honda Sensing safety features such as adaptive cruise control and lane departure warning.</p><p><br></p><p>The exterior exudes elegance, with stylish alloy wheels and LED headlights. With its combination of robust performance, luxurious features, and advanced technology, the 2015 Honda Accord Touring stands as a compelling choice for those seeking a refined and well-equipped midsize sedan.</p><p><br></p><p>for inquires, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 122000, 'km', 14786, '3.5L', '5', '[\"Traction control\", \"Navigation system\", \"Bluetooth\", \"Keyless Entry\", \"Power Seats\", \"Fully Loaded\", \"Leather seats\", \"Sunroof\", \"LED Headlight\", \"Bluetooth Audio\", \"Rearview Camera\", \"Upgraded Soft Leather\", \"Multi-Function Steering Wheel\", \"Comfort Seat\", \"Blind Spot Assist\", \"Lane Keep Assist\", \"Power Seat with Memories\", \"Power Folding Mirror\", \"Bose Sound\", \"Active Curise Control\"]', 2015, '[\"/storage/images/MuRmWlWR6dkC9xIL8yZWOiIA5yzumtQU7x5cvQvm.jpg\", \"/storage/images/DxjI0MCLe46zxaGNXx2GUhj0xi9GlGZ8OEsTrrxJ.jpg\", \"/storage/images/02DpYOAco3RhPgmJq7Ucmr4WdYTjLMgBl3h38B8B.jpg\", \"/storage/images/txIIb02f2NYRN5hoSjiuSLNkj3zE7Km1GfkmoRar.jpg\", \"/storage/images/Jh2WAOgzHTDjyKm0bSDyYLbhDtubeK7hVM1Pjnx0.jpg\", \"/storage/images/MfjY7QJKr4Vvowtfo6YwRK1YHaMTAMih8sGtLfvp.jpg\", \"/storage/images/fJc9QS3LfBB9q9hRaMH7MKOm9p7Ley4T7eoK5rwE.jpg\", \"/storage/images/XIMmFr6sBBjvg6pmJ28MLvqU4MVz0Q0X5WZMBHrk.jpg\", \"/storage/images/EQRYtVwIFHR0ifjjDpOJ0LLkcWKr6Sk7O6rVJKI2.jpg\", \"/storage/images/3OkKkELPIvhcaIFcJskJ60rAB7md3HxmVmGZ7vKr.jpg\", \"/storage/images/sUCUsVrsooLQwYbUZxe9dPEBLDHI4rKehXXzjfXO.jpg\", \"/storage/images/XXIF6MWUZTHS1XrTrrOZY2VHsfPoDfKkG97C6IU8.jpg\", \"/storage/images/EQe8sa6ClbhAIc37uIZXSuCxDZBIUkRwnuZMlkSy.jpg\", \"/storage/images/aDgB3xWQGYwhRlactjYU8Qvsms88FHcdkUN8mgF0.jpg\", \"/storage/images/wyhQtIRZ3zO4GQRIf1KNQxhlh4QSLENIT3pH9VLR.jpg\", \"/storage/images/nbqj1JxNhEpzmN8gqnm4AAkQeKdU89FD8Z6RnTeP.jpg\", \"/storage/images/4uOIFsRETuBepg1gK8vvaWtXGItJWzk7gD42YR2Q.jpg\"]', 11, 0, 1, NULL, '2024-01-24 05:11:55', '2024-02-17 04:50:43', NULL, NULL, NULL, NULL, NULL),
(188, '2008 LEXUS IS250', '2008-lexus-is250', 'Used', 'Black', 'Black', 'Lexus', 'Manual', 'Is250', 'Sedan', 'RWD', '4', 'GAS', 'Premium', '<p>The 2008 Lexus IS 250 is a luxurious and performance-oriented compact sedan that continues to captivate enthusiasts with its refined design and engaging driving dynamics. Powering this elegant sedan is a responsive 2.5-liter V6 engine, delivering 204 horsepower and 185 lb-ft of torque. Mated to a smooth 6-speed manual transmission, the IS 250 offers a sophisticated and dynamic driving experience.</p><p><br></p><p>Inside the cabin, the IS 250 showcases a meticulously crafted interior with high-quality materials and attention to detail. The standard features include leather upholstery, dual-zone automatic climate control, and a premium audio system. Advanced safety features, such as stability control and multiple airbags, contribute to the IS 250\'s reputation for providing a secure driving environment.</p><p><br></p><p>The exterior design features sleek lines, a distinctive grille, and alloy wheels, embodying Lexus\' commitment to blending performance with luxury. With its combination of powerful performance, luxurious amenities, and elegant design, the 2008 Lexus IS 250 remains an enticing choice for those seeking a premium compact sedan experience.</p><p><br></p><p>for inquires, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 129000, 'km', 13786, '2.5L', '5', '[\"Traction control\",\"Leather seats\",\"Power Seats\",\"Keyless Entry\",\"Air Cond. Seats\",\"LED Headlight\",\"Sunroof\",\"Upgraded Soft Leather\",\"Multi-Function Steering Wheel\",\"Sport Seats\",\"Keyless Go\",\"Power Seat with Memories\",\"Bose Sound\",\"Active Curise Control\",\"LED Headlight\",\"Fully Loaded\",\"LED Headlight\"]', 2008, '[\"\\/storage\\/images\\/pAAFu43AwUJKsbO1RUP24AoaOnh6AZOJ2qA9SLpH.jpg\",\"\\/storage\\/images\\/Qt8AUrfHKFvyRcIgWzDSFvwDKbi7iwYUUi35qwLR.jpg\",\"\\/storage\\/images\\/N3sJa0YJD9hkIGPWHqoviQa9g43kBEUAGYjk4gpW.jpg\",\"\\/storage\\/images\\/syNIWn5C2GtkwymoPZtAZBSHYR6WFM2h2wyKCyL9.jpg\",\"\\/storage\\/images\\/1qRFFKRNcepVfGxJ5wldKh4fzIDV1JGB4SnYZAc3.jpg\",\"\\/storage\\/images\\/5FtyqVy7AYZ81ywRXZBVKPzMxoSJ1hnXUERIPKD9.jpg\",\"\\/storage\\/images\\/htVZWkH3hzNLtsCQreXnUTzFjeoGOL2M6EeZxnzz.jpg\",\"\\/storage\\/images\\/huxojXbWkuTBDgbtvrNXClxQ6Z8Rt7CpPwUntI7u.jpg\",\"\\/storage\\/images\\/3XBZpsTOXavlKFJ7kww5a2XBy4Xx95phadBR9XW5.jpg\",\"\\/storage\\/images\\/DuaHx2WUmkSVLSu60WYt2karoeBBUBq1lsiLQfp7.jpg\",\"\\/storage\\/images\\/GHQdpCt9lU54yMhyKQf2H0ShE9ite2tjzAluLpsF.jpg\",\"\\/storage\\/images\\/3y1TIgRcK6UrklE4c7IXawqdnsqfzTmvsk9lmwRt.jpg\",\"\\/storage\\/images\\/I1d3tQsavZKWvoNPzbygUCJjWs9FAQYXqtOGqAYk.jpg\",\"\\/storage\\/images\\/iX5yTgEarGyLwVz3xI3fgiJfErETPnKRjyzX4dXw.jpg\",\"\\/storage\\/images\\/AeXk4xFCgnvYxJzbWzCCEK6UzG8my8QPryf2G3zo.jpg\",\"\\/storage\\/images\\/vF2DgVws6IuuFRMYP40Tee6j00rkrJaud8hIdlVH.jpg\",\"\\/storage\\/images\\/8SaNMFn1FZVjvieCpk3seWNQViRiAKtJlqMYHmD5.jpg\"]', 0, 0, 1, NULL, '2024-01-24 05:17:02', '2024-05-28 05:32:44', NULL, NULL, NULL, NULL, NULL),
(189, '2015 TOYOTA RAV4', '2015-toyota-rav4', 'Used', 'Red', 'Black', 'Toyota', 'Automatic', 'RAV4', 'Suv', 'AWD', '4', 'GAS', 'LE', '<p>The 2015 Toyota RAV4 LE is a practical and reliable compact SUV. Powered by a 2.5-liter engine, it offers a balanced mix of performance and fuel efficiency. With a spacious interior, user-friendly features, and a sleek exterior design, the RAV4 LE is an ideal choice for those seeking versatility and reliability in a compact SUV.</p><p><br></p><p>for inquires, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 164250, 'km', 15786, '2.5L', '5', '[\"Traction control\", \"Bluetooth\", \"Sunroof\", \"All Wheel Drive\", \"Bluetooth Audio\", \"Rearview Camera\", \"Multi-Function Steering Wheel\", \"Active Curise Control\"]', 2015, '[\"/storage/images/iVfgNeM9yUQD2H6ws6JGIjNdSEq173HoxFXPjseb.jpg\", \"/storage/images/ULGyxL2q1tf9jpJPNgWycfTaBpPkiaYEaJzg7kwv.jpg\", \"/storage/images/AZknVDJJ35TRR91MlwRLg5fGTVE0okkhFEQtAOUb.jpg\", \"/storage/images/pWiCeIWZrbXN2Z0KdZlcKIOCyfqTodCAoRT13i2q.jpg\", \"/storage/images/Sm0nmpozJH8idhsSiXfOfEnOr8PfNxq4bIkNG12F.jpg\", \"/storage/images/T9zOE2lxEHQTRGfojIORgq2EXEHhT3bSws5kBFhJ.jpg\", \"/storage/images/gJYPpdiVabGZjmbUsV0pix3seKuiDwkzDPPY2O2j.jpg\", \"/storage/images/vakvy3JzI2qUlUxmAMtrDlsu9MPvjTUDMU95FjnF.jpg\", \"/storage/images/bkQpH7JzBYF9Kb3GyxgWwVivYiePIl7wEwGOe3UK.jpg\", \"/storage/images/kmiPf6I8TCDt3PUR9pkJkIdBYGn0IUNg2dska9U8.jpg\", \"/storage/images/uD4iyO1mdnYDtf1PEwNfD4Pwa8ZCkI9suNhCjA7y.jpg\", \"/storage/images/jkH0KGFPj0dKd3aMeCH01BzcKZ0zipwFL8eZsOnJ.jpg\", \"/storage/images/8LSHaziRX1ezjshR1H5W2YOPKHD07yBF9sEj7tGJ.jpg\", \"/storage/images/Db5c2b3xZHZ0ukyfdVhLhVPdP0VbHQmFGfHqxmZD.jpg\", \"/storage/images/a