(190, '2021 HYUNDAI VENUE SEL', '2021-hyundai-venue-sel', 'Used', 'White', 'Black', 'Hyundai', 'Automatic', 'VENUE', '4 Door', 'FWD', '4', 'GAS', 'SEL', '<p>The 2021 Hyundai Venue SEL is a compact and stylish SUV powered by a fuel-efficient 1.6-liter engine. Equipped with modern features like touchscreen infotainment, Apple CarPlay, and Android Auto, it offers a comfortable and connected driving experience. With a distinctive design and safety features, the Venue SEL is an ideal choice for urban living.</p><p><br></p><p>for inquires, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 75600, 'km', 19995, '1.6L', '5', '[\"Traction control\",\"Bluetooth\",\"Bluetooth Audio\",\"Rearview Camera\",\"Multi-Function Steering Wheel\",\"Active Curise Control\",\"Navigation system\",\"Keyless Entry\",\"Fully Loaded\",\"Sunroof\",\"Blind Spot Assist\",\"Keyless Go\"]', 2021, '[\"\\/storage\\/images\\/G4RPoWNvpLYcXJUwrckkNZWMe4ZTlJavQcbFGdte.jpg\",\"\\/storage\\/images\\/Dg0AY0RoyGeSICFbbECh8DAf22QYj1K4a8NYBXlL.jpg\",\"\\/storage\\/images\\/CcDQEF29JFzUPidTOtGmgvqUWZzjY5wclz7DLsff.jpg\",\"\\/storage\\/images\\/aa38KaaXuoYfJ5BRyjrreEB3RcXt3hz95hCvi0Ht.jpg\",\"\\/storage\\/images\\/vkWoIjeM6sWqhGYACjPNvHZpAXFePQ0Pi0Bw5FAu.jpg\",\"\\/storage\\/images\\/X0U0fSeHcH7D0BIajcQaDXXPxHIWeteGYRIw10nP.jpg\",\"\\/storage\\/images\\/N4e64clOc7gKdEHZPRX1SArybIGqpIr4NULYKOZL.jpg\",\"\\/storage\\/images\\/zk2cMb5HSmPuPdae2DQyrgyyYb0xkSup25IfauS1.jpg\",\"\\/storage\\/images\\/prG8i526YKV1X5n61NAUVblLKEl1V1zPX8wbh3h2.jpg\",\"\\/storage\\/images\\/WadqGtLFMhXRp1V2pfaLSd8OwqTIQblKxo61zuKH.jpg\",\"\\/storage\\/images\\/Hqxzryg0a70zh5cyxZHWUPboetgBINLNLbneZLSc.jpg\",\"\\/storage\\/images\\/I3Zb6GT7jU2s69IaFr92DEYrurqlgpR