(208, '2018 DODGE RAM 1500', '2018-dodge-ram-1500', 'Used', 'Red', 'Black', 'Dodge', 'Automatic', 'RAM 1500', 'Pickup', '4WD', '4', 'GAS', 'CLASSIC TRADESMEN', '<p>The 2018 Dodge Ram 1500 Classic Tradesmen is a rugged and reliable pickup truck designed for those who demand performance and versatility. Under the hood, it features a potent 3.6-liter V6 engine, capable of delivering 305 horsepower and 269 lb-ft of torque, ensuring ample power for towing and hauling tasks.</p><p><br></p><p>The Tradesmen\'s durable construction and robust suspension make it well-suited for tackling tough terrain and heavy-duty workloads. Its spacious and functional interior provides comfortable seating for up to six passengers, along with ample storage compartments to stow gear and equipment.</p><p><br></p><p>Equipped with practical features like a spray-in bedliner and trailer sway control, the Ram 1500 Classic Tradesmen is ready to handle any job with ease. Whether you\'re navigating city streets or venturing off-road, this dependable truck offers a smooth and controlled ride, making it an ideal companion for both work and play.</p><p><br></p><p>for inquiries, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 109000, 'km', 25786, '3.6L', '5', '[\"Traction control\",\"Bluetooth\",\"All Wheel Drive\",\"Bluetooth Audio\",\"20 Sport Wheels\",\"Rearview Camera\",\"Towing Package\",\"Multi-Function Steering Wheel\",\"Comfort Seat\",\"Active Curise Control\"]', 2018, '[\"\\/storage\\/images\\/4FcPdHamCEyyvlC8yhMZqp5JgzqwQNKGPScikmJA.jpg\",\"\\/storage\\/images\\/1OzI5Cu9mwAYc6j1PUhsGcRBLGd3RtE3D78XIO7w.jpg\",\"\\/storage\\/images\\/Xd1T3zc8rQrgBGu2eyGFYecIK5Ac8oahNQx9NgF6.jpg\",\"\\/storage\\/images\\/lLCjCSds3gbGSxd5y3zZhhaVkQSH4S3ELCo5FwuC.jpg\",\"\\/storage\\/images\\/p004oFSOnSzmOBC9n1Y9xr7wZ9yAp9RYNNENdAl8.jpg\",\"\\/storage\\/images\\/7zXXTOCSV368eB4tcfWF22tmcw3yMlx5Q8o1Anu4.jpg\",\"\\/storage\\/images\\/qqUD33VknPUkqsdS6YYiuuFgYgHeMSnacKbpOrsy.jpg\",\"\\/storage\\/images\\/NtNiWZ5i4B1tfg1BM12D1NTlGBh46spL6jexhOoS.jpg\",\"\\/storage\\/images\\/dmVyMSihBJNSuYseLWcguKgM4IeXIYYM7RlpH5oP.jpg\",\"\\/storage\\/images\\/N4XLBhBGvtUQvk7Ux3eP9mF3mug9f4kgxTlGADJ0.jpg\",\"\\/storage\\/images\\/0wSkCYwijjfBW803xGSvhF1hCOnWjduZgsLbVx9t.jpg\",\"\\/storage\\/images\\/03WcbNRoYyaBLUT633oOAnfz8JP3eseBj47UMKht.jpg\",\"\\/storage\\/images\\/F7NtHRUBCmU5D9vSRD6XKj4fcZij3FJDXAPqKv7J.jpg\",\"\\/storage\\/images\\/rUs1MKkKM3xEuGCRxA5YaNDSWDwczqElgZ2HzKND.jpg\",\"\\/storage\\/images\\/xshXvK1BB4IvEoQjtYOvN4l2JDO2rYtN0VZdzVn4.jpg\",\"\\/storage\\/images\\/awvuTNfqD65e32i9iXOxmwnnLK4gUXRSSarsxAI7.jpg\"]', 0, 0, 1, NULL, '2024-03-29 05:56:19', '2024-06-10 07:42:34', NULL, NULL, NULL, NULL, NULL),
(209, '2013 INFINITI FX37', '2013-infiniti-fx37', 'Used', 'Purple', 'Beige', 'Infiniti', 'Automatic', 'FX37', '4 Door', 'AWD', '4', 'GAS', 'Premium', '<p>The 2013 Infiniti FX37 is a luxury crossover SUV that seamlessly blends style, performance, and comfort. With its striking exterior design featuring sleek lines and a bold front grille, the FX37 makes a statement on the road.</p><p><br></p><p>Under the hood, it is powered by a potent 3.7-liter V6 engine, delivering a spirited 325 horsepower and 267 lb-ft of torque. Paired with a smooth seven-speed automatic transmission, the FX37 offers responsive acceleration and dynamic handling, ensuring an exhilarating driving experience.</p><p><br></p><p>Inside, the FX37 boasts a luxurious and well-appointed cabin, with premium materials and craftsmanship throughout. Comfortable leather seats, along with advanced technology features such as a touchscreen infotainment system, navigation, and a premium audio system, create a refined and enjoyable driving environment.</p><p><br></p><p>Safety is paramount in the FX37, with features like adaptive cruise control, lane departure warning, and a surround-view camera system providing peace of mind for both driver and passengers.</p><p><br></p><p>With its combination of powerful performance, luxurious amenities, and advanced safety features, the 2013 Infiniti FX37 offers a truly exceptional driving experience in the competitive luxury SUV segment.</p><p><br></p><p>for inquiries, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 173540, 'km', 13500, '3.7L', '5', '[\"Traction control\",\"Navigation system\",\"Bluetooth\",\"Leather seats\",\"Fully Loaded\",\"Power Seats\",\"Keyless Entry\",\"Sunroof\",\"LED H