(216, '2023 CHEVROLET CAMARO RS', '2023-chevrolet-camaro-rs', 'Used', 'Grey', 'Red', 'Chevrolet', 'Automatic', 'Camaro', 'Coupe', 'RWD', '4', 'GAS', 'RS 2LT', '<p>The 2023 Chevrolet Camaro RS 2LT is a sleek and stylish sports coupe that balances performance and comfort. Equipped with a 3.6L v6 engine which produces 335 HP and 284 torque. paired with a 6-speed manual or optional 10-speed automatic transmission. This model delivers sharp handling, with rear-wheel drive and sport-tuned suspension enhancing its agility.</p><p><br></p><p>The RS Package adds sporty styling elements, including a unique grille, dark-tinted taillamps, and 20-inch aluminum wheels. Inside, the Camaro 2LT comes equipped with premium features such as leather-trimmed seats, an 8-inch touchscreen infotainment system with Apple CarPlay and Android Auto, a Bose premium audio system, and dual-zone climate control. Safety tech includes a forward collision alert, rear cross-traffic alert, and a rearview camera.&nbsp;</p><p><br></p><p>The 2023 Camaro RS 2LT is a performance-oriented vehicle with impressive acceleration, a modern interior, and advanced technology for driving enthusiasts.</p><p><br></p><p>for inquiries, contact one of our sales representatives:</p><p><br></p><p>Ashraf Alighazi</p><p>Phone: 647-521-7186</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Emad Alighazi</p><p>Phone: 647-573-2552</p><p>Email: xtremeinc.86@gmail.com</p><p><br></p><p>Omar Alighazi</p><p>Phone: 647-545-6393</p><p>Email: xtremeinc.86@gmail.com</p>', 'sold', 21000, 'km', 34999, '3.6L', '4', '[\"Traction control\",\"Navigation system\",\"Bluetooth\",\"Keyless Entry\",\"Power Seats\",\"Fully Loaded\",\"Leather seats\",\"Sunroof\",\"LED Headlight\",\"Air Cond. Seats\",\"Bluetooth Audio\",\"Rearview Camera\",\"Multi-Function Steering Wheel\",\"Paddle Shift\",\"Sport Seats\",\"Blind Spot Assist\",\"Lane Keep Assist\",\"Keyless Go\",\"Bose Sound\",\"Active Curise Control\",\"LED Headlight\",\"Remote start\",\"20\\\" Sport Wheels\",\"HEATED SEATS\"]', 2023, '[\"\\/storage\\/images\\/OsV7tcZK8LAgej39W6P9vSOqSJfXqBU1hnmM4iYE.jpg\",\"\\/storage\\/images\\/f5SohBa6Zeb3wocGiP04HD1r75V0xXSuWvmE93gv.jpg\",\"\\/storage\\/images\\/65AP866KTFLvSUiYoULr1SWsiN83q79puYX6ptrv.jpg\",\"\\/storage\\/images\\/ciAh3WPTCOc673Lbgltho1HZXDTc3s01JnQl4YgO.jpg\",\"\\/storage\\/images\\/yOoqHErSFVDyawzr1dewQZdwmsXEG7iqrpe5jn8H.jpg\",\"\\/storage\\/images\\/4ENIXIiAofZEcHlrzEalgEy8KlIwZgJNCI4IWd04.jpg\",\"\\/storage\\/images\\/WFyAC6DqA9s9aZYyxUMY71JlL75UoMA7Bs7fTuaF.jpg\",\"\\/storage\\/images\\/flSMbqhczAcxdBhupMufFpbx4KggSkDJl4TTbIhU.jpg\",\"\\/storage\\/images\\/W6A9fHR9zjsUQ0sn6x59Pnj5PqWwC5HDsE2EwtWQ.jpg\",\"\\/storage\\/images\\/u6xP9xCmCfexMIaL9qZ9vS1CaDqMgDTqyZEIWCjD.jpg\",\"\\/storage\\/images\\/EoMPhMNmc1lycmddlNLj32cxRzcQF3vP1muUrUAy.jpg\",\"\\/storage\\/images\\/dB44PztvDw3for5hmQETOFWc4yz8lUIfjqBGdjHp.jpg\",\"\\/storage\\/images\\/Jq0xh2HvNQ82WuI11YIV7Y635qPOzeSLaPjDXVSM.jpg\",\"\\/storage\\/images\\/OVccRceZOU2RU3WdMTZ3hi70L5Sq7yXfTsjLzZ9p.jpg\",\"\\/storage\\/images\\/W97ZdKqQJEj1YcFjnkNc7oVIeieYqXqdmCEGaK9R.jpg\",\"\\/storage\\/images\\/1VRFgFDdIe5tnkz6yoSlp5lQlgWPd3uuU6O2ETTa.jpg\",\"\\/storage\\/images\\/tWEqrFCWdTipiicdD0MSaVuhAqsd8E7YmzGeyERP.jpg\"]', 0, 0, 1, '2025-08-26 22:10:20', '2024-10-01 22:43:16', '2025-08-26 22:10:20', NULL, 'https://vhr.carfax.ca/?id=w13fehAOU1JIglBf8VQw4QveUVBJHK6y#accident-damage-section', '1G1FD1RS1P0108395', '13.1L', '8.1L');
