(244, '2022 HONDA CIVIC SI', '2022-honda-civic-si', 'Used', 'Black', 'Black', 'Honda', 'Manual', 'Civic', 'Sedan', 'FWD', '4', 'GAS', 'SI', '<p><strong>Looking for a sporty daily driver with great fuel economy and performance?</strong></p><p> This <strong>2022 Honda Civic Si</strong> delivers turbocharged power, sharp handling, and proven Honda reliability—all in a sleek, driver-focused package. Powered by a 1.5L turbocharged 4-cylinder engine paired with a 6-speed manual transmission, the Civic Si is built for those who love to drive without sacrificing efficiency.</p><p><strong>Key Features:</strong></p><ul><li>1.5L Turbocharged I4 Engine with 6-Speed Manual Transmission</li><li>Apple CarPlay &amp; Android Auto</li><li>Sport Seats with Red Stitching</li><li>Dual-Zone Climate Control</li><li>Power Sunroof</li><li>Honda Sensing® Safety Suite</li><li>18\" Alloy Wheels</li><li>Premium Audio System</li></ul><p><strong>Fuel Economy:</strong></p><p> City: 8.7 L/100 km</p><p> Highway: 6.4 L/100 km</p><p> Combined: 7.6 L/100 km</p><p>This Civic Si is in excellent condition and ready for its next enthusiast. Whether you\'re commuting or carving up backroads, it delivers a perfect balance of excitement and practicality.</p><p>✅ <strong>2-Year Engine &amp; Transmission Warranty Included</strong></p><p> ✅ <strong>Financing Available</strong></p><p><strong>Contact us today to schedule a test drive!</strong></p><p><br></p>', 'sold', 51000, 'km', 24995, '1.5L', '5', '[\"Parking sensors\",\"Traction control\",\"Navigation system\",\"Bluetooth\",\"Keyless Entry\",\"Fully Loaded\",\"Sunroof\",\"LED Headlight\",\"Bluetooth Audio\",\"Rearview Camera\",\"Sport Seats\",\"Multi-Function Steering Wheel\",\"Blind Spot Assist\",\"Lane Keep Assist\",\"Keyless Go\",\"Active Curise Control\",\"Bose Sound\",\"Heated steering\",\"Remote start\",\"HEATED SEATS\"]', 2022, '[\"\\/storage\\/images\\/1RJIHrbrJBBG8LilmAQWMAtkNuGkCCL2LzNJpyEx.jpg\",\"\\/storage\\/images\\/47yuCckltktsyZhYmi3Goi3RdXWOAsxKOoVD5geY.jpg\",\"\\/storage\\/images\\/SL3NVsfuokrCzBGrOyyOVySuBuCbhFo8WYQjVyal.jpg\",\"\\/storage\\/images\\/jybCUfWeB66RBrGCI5z2sPR4uSbo1bkeCdB0vb51.jpg\",\"\\/storage\\/images\\/O7c4vUNQasIFykmJSPlnUxVWWFFjsdcv6QYP9oYt.jpg\",\"\\/storage\\/images\\/nOnrZuWbcIPctuIfRWRXKgmh2yefcGe8qcgXq7dA.jpg\",\"\\/storage\\/images\\/uH6UJ6N32TIGj3ubqaGlcTH7SWbChmMvAzhCMNOQ.jpg\",\"\\/storage\\/images\\/7nZnoAY92omaoT9Ckiq9mYxQLBvGuTR9stJsnKkb.jpg\",\"\\/storage\\/images\\/e2BOB5vueM9FwKwg5qr2de8gPu0GrxacfNvLYufI.jpg\",\"\\/storage\\/images\\/v0hh66ml6s6tb0O97ukiueeDUzmIrsWbn7hSGCSu.jpg\",\"\\/storage\\/images\\/VpYmr9YN6jdVCq8fI2sFHtd7OZh3RUhMBfgu8tvQ.jpg\",\"\\/storage\\/images\\/M0tjbSJY3T2GStSccidyWLbkqrMogxEcb3KoDXoC.jpg\",\"\\/storage\\/images\\/MLkL93uZvXL3xj0rRkbz7CK3wikgCNKafU5kn6g8.jpg\",\"\\/storage\\/images\\/2sIrQu36jRHuFHaKAl6Scy4LalPyzaO4O2fZ3ZpO.jpg\",\"\\/storage\\/images\\/MdZiBpy4SBooYBbY9DsGaln58LOiNJ7vXm9xl9zt.jpg\",\"\\/storage\\/images\\/GwVpXAbDhnIG9sUIeDdEgzcOV02ejUo58ePxWNuN.jpg\",\"\\/storage\\/images\\/OwrfzkcPz9347kiXU4Jy9jIH8JaEjjpNBZL0exo1.jpg\",\"\\/storage\\/images\\/KccF31MCCr60r3JxQ6GXCNUPF1W5biCEeVOnfXe7.jpg\",\"\\/storage\\/images\\/AtbsXoT03GTeRNxnVXHtJEmehiFtZT8KVQS52COE.jpg\",\"\\/storage\\/images\\/4UHlkv6kBXXsvHklR0w0lHecrPs6NADZRNANlXXh.jpg\"]', 0, 0, 1, NULL, '2025-05-05 22:27:30', '2025-08-26 22:12:17', NULL, 'https://vhr.carfax.ca/?id=w51F2eAbEZFQDmRKBOjI%2BOCvNb0R4IBE', '2HGFE1E52NH080220', '8.7L', '6.4L'),
(245, '2016 BMW X5 PREMIUM', '2016-bmw-x5-premium', 'Used', 'Black', 'Brown', 'BMW', '8 Speed Automatic', 'X5', 'Suv', 'AWD', '4', 'GAS', 'Premium', '<p>The 2016 BMW X5 xDrive35i Premium seamlessly blends luxury, performance, and versatility in a mid-size SUV built to impress. Under the hood, a refined 3.0L TwinPower Turbo inline-6 engine delivers a smooth yet powerful driving experience with 300 horsepower and 300 lb-ft of torque. Paired with BMW’s intelligent xDrive all-wheel drive and an 8-speed automatic transmission, this SUV is engineered for confident handling in all conditions—whether you\'re navigating city streets or weekend getaways.</p><p>With a sophisticated interior, high-end finishes, and cutting-edge technology, the X5 offers premium comfort for every journey.</p><p>Key Features:</p><ul><li>3.0L TwinPower Turbo Inline-6 Engine with 300 hp &amp; 300 lb-ft of torque</li><li>8-Speed Automatic Transmission with Manual Shift Mode</li><li>xDrive Intelligent All-Wheel Drive System</li><li>Panoramic Sunroof</li><li>Navigation System with iDrive Interface</li><li>Premium Dakota Leather Upholstery</li><li>Heads-up display</li><li>Heated Front and Rear Seats</li><li>Power Adjustable Front Seats with Memory Function</li><li>Rearview Camera with Parking Sensors</li><li>Keyless Entry and Push-Button Start</li><li>Dual-Zone Automatic Climate Control</li><li>Hands-Free Power Liftgate</li><li>Bluetooth, USB, and AUX Connectivity</li><li>Harman Kardon Surround Sound System</li></ul><p>Fuel Economy:</p><ul><li>City: 13.0 L/100 km</li><li>Highway: 9.8 L/100 km</li><li>Combined: 11.6 L/100 km</li></ul><p>Whether you\'re seeking refined comfort, advanced driving dynamics, or versatile utility, the 2016 BMW X5 xDrive35i Premium is ready to elevate every drive.</p><p>Contact us today to schedule your test drive and experience true BMW luxury and performance!</p><p>✅ 2 years extended warranty included</p><p> ✅ Financing available for all kinds of credit</p><p><br></p>', 'available', 144350, 'km', 19995, '3.0L', '5', '[\"Parking sensors\",\"Traction control\",\"Navigation system\",\"Bluetooth\",\"Xenon\",\"Keyless Entry\",\"Power Seats\",\"Fully Loaded\",\"Leather seats\",\"Panoramic Sunroof\",\"All Wheel Drive\",\"Bluetooth Audio\",\"Rearview Camera\",\"Upgraded Soft Leather\",\"Surroundview Camera\",\"Towing Package\",\"Paddle Shift\",\"Multi-Function Steering Wheel\",\"Harman Kardon Sound\",\"Keyless Go\",\"Lane Keep Assist\",\"Blind Spot Assist\",\"Power Seat with Memories\",\"Power Tailgate\",\"Power Folding Mirror\",\"Head-Up Display\",\"Active Curise Control\",\"Heated steering\",\"HEATED SEATS\",\"HILL DESCENT\"]', 2016, '[\"\\/storage\\/images\\/YqqOiZ7BwqykoOkeArGrQj0zlzEiYGTatua54rCH.jpg\",\"\\/storage\\/images\\/evGTg8zP6rVKTvyJ7nZBn5qb2J5SYDx3mOFxYqEF.jpg\",\"\\/storage\\/images\\/6xZrqa6v0NDwFeJ2RhEARm0caiHDlzMK69g9RjrT.jpg\",\"\\/storage\\/images\\/vCYCOqjSMfXwm2VHpdB2viEHGDRJz6RrqbW906oT.jpg\",\"\\/storage\\/images\\/YQDqFO2ztICqu8M4nbLqNesjP5xoHSP1BxYBGb4c.jpg\",\"\\/storage\\/images\\/sIQWGBoohsSunbhwSx6jretA7ja6BmNpbG1uF8Mz.jpg\",\"\\/storage\\/images\\/lS8SYtr92gGLVC4GWtVHhaJfLHiIJkQxXEOuvVGa.jpg\",\"\\/storage\\/images\\/USPBQ8UDA2FJLNeSo3BRPODIMQiPcGsS2ejy8xzq.jpg\",\"\\/storage\\/images\\/CdL9z4EmonLf4uUYkeqHWjpr9C3gFoKPDQV2UCfF.jpg\",\"\\/storage\\/images\\/WCf5CsI2RDliml2SneUddGfjm2CAYvkBcW0llrut.jpg\",\"\\/storage\\/images\\/QXZlT2HewmHD5xKmeSL8tjEVfVhyU9NtpWcGopD3.jpg\",\"\\/storage\\/images\\/zNefrQNwz4RhutO4vnz3oKr1pJxUZfdzlbhtecGW.jpg\",\"\\/storage\\/images\\/kjsqUDu3Jvy9dr72FG13fNsVKGTLgx6aFPVLNdZR.jpg\",\"\\/storage\\/images\\/3nyVLatphJPl2R6s78j7Zso8FpglHKPcKPdsvZCR.jpg\",\"\\/storage\\/images\\/qN00TRgO0j32GjFesXoQUtRwVX4UaHdRg8i6NHCG.jpg\",\"\\/storage\\/images\\/KC4ZcLsR7cCDEEuNFFvo75km23kBfxJqdyNzswmy.jpg\",\"\\/storage\\/images\\/HiT6HwMfYwW52mhgXdQ712qsizrxzqIvSMXJ0fPC.jpg\",\"\\/storage\\/images\\/yJXwzbzd7y85riIVi24GULAdj7mCiFIdAoViMfAX.jpg\",\"\\/storage\\/images\\/mqfSeQ1nz19RwZ0xbSFI9XfHhoPeDXKgchY5px4K.jpg\",\"\\/storage\\/images\\/QadpolnVMDJQ7C91FTAE0NRxpef1m8H0s37frWOT.jpg\"]', 0, 1, 1, '2025-08-26 22:08:19', '2025-05-12 22:39:40', '2025-08-26 22:08:19', NULL, 'https://vhr.carfax.ca/?id=tLeExDJqruaO97sdi2kXZLLcL2sE2u8s', '5UXKR0C50G0P34247', '13.0L', '9.8L'),
(246, '2020 HONDA ODYSSEY LX', '2020-honda-odyssey-lx', 'Used', 'Black', 'Black', 'Honda', 'Automatic', 'ODYSSEY', 'Minivan', 'FWD', '4', 'GAS', 'LX', '<p><br></p><p>The 2020 Honda Odyssey LX is the ultimate family vehicle, delivering practicality, comfort, and Honda’s legendary reliability in a sleek and spacious minivan. Powered by a responsive 3.5L V6 engine producing 280 horsepower and paired with a smooth 10-speed automatic transmission, the Odyssey LX offers confident acceleration and a refined ride for all your journeys—whether it’s a quick school run or a cross-country adventure.</p><p>With thoughtful features, a versatile interior, and advanced safety technology, the Odyssey is built to keep families connected, comfortable, and safe.</p><p>Key Features:</p><ul><li>3.5L i-VTEC V6 Engine with 280 hp</li><li>10-Speed Automatic Transmission with Paddle Shifters</li><li>Honda Sensing® Safety Suite (Collision Mitigation Braking, Lane Keeping Assist, Adaptive Cruise Control, Road Departure Mitigation)</li><li>8-Passenger Seating with Magic Slide® 2nd-Row Seats</li><li>Rearview Camera with Guidelines</li><li>5-Inch Display Audio System with Bluetooth® Streaming</li><li>Push-Button Start and Remote Entry</li><li>Tri-Zone Automatic Climate Control</li><li>Power Front Seats</li><li>Active Noise Cancellation (ANC)</li><li>LED Daytime Running Lights</li><li>USB Audio Interface &amp; Speed-Sensitive Volume Control</li><li>Ample Cargo Space with One-Motion 60/40 Split 3rd-Row Magic Seat®</li></ul><p>Fuel Economy:</p><ul><li>City: 12.2 L/100 km</li><li>Highway: 8.5 L/100 km</li><li>Combined: 10.6 L/100 km</li></ul><p>From daily errands to long road trips, the 2020 Honda Odyssey LX is designed to meet the needs of modern families with safety, comfort, and class-leading flexibility.</p><p>Contact us today to book your test drive and see why the Odyssey is Canada’s favorite family minivan!</p><p>✅ 2 years extended warranty included</p><p> ✅ Financing available for all kinds of credit</p><p><br></p>', 'available', 92300, 'km', 24995, '3.5L', '7', '[\"Bluetooth\",\"Keyless Entry\",\"Bluetooth Audio\",\"Rearview Camera\",\"7 Seats\",\"Multi-Function Steering Wheel\",\"Lane Keep Assist\",\"Keyless Go\",\"Advance Key\",\"Active Curise Control\",\"HEATED SEATS\"]', 2020, '[\"\\/storage\\/images\\/NLqhvbbqzyBoXieZhprVQAR6kthG2NdNj79qnmp3.jpg\",\"\\/storage\\/images\\/HK4fxyAZ2TFYdSQ5VOMokedJNCQiUIuq74DUp6u4.jpg\",\"\\/storage\\/images\\/nnKvDK6SS70QCeOWtr1bZ9icO9E7FltllnoOEb5w.jpg\",\"\\/storage\\/images\\/mw9TrntEsIhg4ADoRKGBaoORXOj1aE9JVN2Gtgfb.jpg\",\"\\/storage\\/images\\/3vCn1gsgV629xdu982JlWiyL729Daxu5ThhUfdBV.jpg\",\"\\/storage\\/images\\/KusWdoeaJcAa4t5urtXVN1uLdFrqD5GkCaF9wEPX.jpg\",\"\\/storage\\/images\\/7KcHuEKWVpvdDzXT2jkXWraSfWJ2VCGuNQzwSlKG.jpg\",\"\\/storage\\/images\\/pU9rmy9fSucAtUYyjYjuv8Htnanp088tXPiopGi5.jpg\",\"\\/storage\\/images\\/TsFJx6eAbZvtCtFr9ufYrdCnwcpsjEsyKbEDVAvc.jpg\",\"\\/storage\\/images\\/bGrF38iVQn5TAnYXm0guBZUbUXD2iuaInGFKl6Bc.jpg\",\"\\/storage\\/images\\/mYVSMFzjJzllla1MdeT1YlfMHhrHgaNSZHmqCIZy.jpg\",\"\\/storage\\/images\\/lN9cwba4NY3KxZ90WjDhRibhEjocg9qqF0Z9Y1KW.jpg\",\"\\/storage\\/images\\/rx4xhJXcOvaYGBsfMAxYy2VH3tYrOC6Eyv5bF10G.jpg\",\"\\/storage\\/images\\/W6Zj6ioI8Zk7vpau1nvG47XXcxjAhq5YcCE8auzi.jpg\",\"\\/storage\\/images\\/vJr39iUdBwa1p5WkdQpmQBGxPcXb215FRwNOnbaJ.jpg\",\"\\/storage\\/images\\/EE5DgCRBfnIAHCXOoU6cN3bla6oduY2HsJR9cvUR.jpg\",\"\\/storage\\/images\\/QYjzSEkVsInNQH0pzJS4ouUyoLczBaEqmSvTB8kG.jpg\"]', 0, 0, 1, '2025-08-26 22:08:16', '2025-05-12 23:11:55', '2025-08-26 22:08:16', NULL, 'https://vhr.carfax.ca/?id=eV89kLTgCXLPU1PSx1ASJ4nRvU2k6c%2Bm', '5FNRL6H22LB502330', '12.2L', '8.5L'),
(247, '2016 DODGE GRAND CARAVAN SE', '2016-dodge-grand-caravan-se', 'Used', 'Black', 'Black', 'Dodge', 'Automatic', 'GRAND CARAVAN', 'Minivan', 'FWD', '4', 'GAS', 'SE', '<p><br></p><p>The 2016 Dodge Grand Caravan SE is a practical and dependable family minivan designed to deliver comfort, convenience, and exceptional value. Powered by a robust 3.6L Pentastar V6 engine with 283 horsepower, this versatile people-mover combines strong performance with smart features to make every drive easier—whether you\'re commuting, carpooling, or heading out on a road trip.</p><p>With flexible seating and cargo solutions, the Grand Caravan SE adapts to your lifestyle, offering impressive interior space and everyday functionality at an unbeatable price point.</p><p>Key Features:</p><ul><li>3.6L Pentastar V6 Engine with 283 hp</li><li>6-Speed Automatic Transmission</li><li>7-Passenger Seating with 2nd &amp; 3rd Row Stow ‘n Go® Seating</li><li>Dual-Zone Climate Control</li><li>Keyless Entry</li><li>Rear Air Conditioning and Heater</li><li>AM/FM/CD/MP3 Audio System with AUX Input</li><li>Cruise Control</li><li>Power Windows, Locks, and Mirrors</li><li>Tilt and Telescopic Steering Wheel</li><li>17\" Steel Wheels with Covers</li><li>Advanced Multistage Front Airbags, ABS, and Stability Control</li><li>Fold-Flat 3rd Row for Expansive Cargo Space</li></ul><p>Fuel Economy:</p><ul><li>City: 13.7 L/100 km</li><li>Highway: 9.4 L/100 km</li><li>Combined: 11.8 L/100 km</li></ul><p>The 2016 Dodge Grand Caravan SE is a trusted choice for families seeking a reliable, affordable, and spacious vehicle with all the essentials.</p><p>Contact us today to schedule your test drive and discover the value-packed performance of the Grand Caravan!</p><p>✅ 2 years extended warranty included</p><p> ✅ Financing available for all kinds of credit</p><p><br></p>', 'available', 163000, 'km', 10995, '3.6L', '7', '[\"Traction control\",\"Keyless Entry\",\"7 Seats\",\"Towing Package\",\"Active Curise Control\"]', 2016, '[\"\\/storage\\/images\\/b52Zklw94gRFY5TDRlthd2rOvRUWfx9wJQvtjfHt.jpg\",\"\\/storage\\/images\\/sbFA9vT5YVwUAAkGIFd61LvCLqHzrYVWbIusEX5o.jpg\",\"\\/storage\\/images\\/dCN9YEZ5ZD4fD9VkA9lUupMHU39zL3QAvMrQfDfQ.jpg\",\"\\/storage\\/images\\/uPDA4hwMeNw6DOgdVOajpQlZjfqQAwDUEiujmXhT.jpg\",\"\\/storage\\/images\\/KG4P4J3zvlp24c6B51L1vG6u2Sx8zLMKvJe69wYA.jpg\",\"\\/storage\\/images\\/eBuhOktYHiAIXOWegSoRu0kOBwFH3MLDwzxATAVy.jpg\",\"\\/storage\\/images\\/eJKUjuGddlSZbQVV5laApri3Lmh19v7uLaWQaaz0.jpg\",\"\\/storage\\/images\\/24eeCYtB9PGND4ZgBohoYaNMbPhLsjrfE6T3VaGR.jpg\",\"\\/storage\\/images\\/bcDpflAXJvypxBApAFeR7bsXyBNvEfkwiwg5bBCb.jpg\",\"\\/storage\\/images\\/RUKVzhwZupPwOuqwxDyTQ2NhoYtR4aZnkhGzMjer.jpg\",\"\\/storage\\/images\\/k9GSbYp4fCdhZyqRlzcbfTVGeMguMcWLRirxqnaT.jpg\",\"\\/storage\\/images\\/ic4zhZeJQDUIfCb2qUoD4FEgmMd7LJI26c8mcHMu.jpg\",\"\\/storage\\/images\\/hN4CQb6jBnX0C3i4fP3pQShNgOdI6N0neAwhIkDr.jpg\",\"\\/storage\\/images\\/jWL3fKuzkyj57WfYPXbdU4SMUp1WHaoHE0MntDR6.jpg\",\"\\/storage\\/images\\/v5MM8QO2r5Hxg3fHtwusC2Jlkgcv4mYnqRxlLlbX.jpg\",\"\\/storage\\/images\\/t5Imf0PnSqhMcDmjCXVSQK1MgAHeJgfdZZYL4lKE.jpg\"]', 0, 0, 1, '2025-08-26 22:08:13', '2025-05-12 23:26:15', '2025-08-26 22:08:13', NULL, 'https://vhr.carfax.ca/?id=qr6R8u4zmZpjsZd8Y9%2BUDjKU0t2uGsBu', '2C4RDGBG7GR145244', '13.7L', '9.4L');
INSERT INTO `cars` (`id`, `name`, `slug`, `technical_condition`, `ext_color`, `int_color`, `make`, `transmission`, `model`, `body_type`, `drive`, `door`, `fuel`, `trim`, `description`, `availability`, `mileage`, `mileage_unit`, `price`, `engine`, `seats`, `features`, `year`, `images`, `featured_image_index`, `featured`, `user_id`, `deleted_at`, `created_at`, `updated_at`, `video_link`, `carfax_link`, `vin`, `city_fuel_consumption`, `highway_fuel_consumption`) VALUES
(248, '2016 FORD FOCUS TITANIUM ELECTRIC', '2016-ford-focus-titanium-electric', 'Used', 'Blue', 'Beige', 'Ford', 'Automatic', 'FOCUS', 'Hatchback', 'FWD', '4', 'Electric', 'TITANIUM', '<p><br></p><p>The 2016 Ford Focus Electric Titanium offers a bold step into the future of driving—zero emissions, sleek styling, and premium comfort, all in one efficient package. Powered by a 107 kW (143 hp) electric motor and a 23 kWh lithium-ion battery, the Focus Electric delivers instant torque, smooth acceleration, and a whisper-quiet ride. Perfect for urban commuting and environmentally-conscious drivers, it blends cutting-edge EV technology with the upscale features of the Titanium trim.</p><p>Enjoy the perks of electric driving without compromising on comfort or convenience.</p><p>Key Features:</p><ul><li>107 kW Electric Motor (143 hp)</li><li>1-Speed Automatic Transmission</li><li>23 kWh Lithium-Ion Battery</li><li>Estimated Range: Up to 130 km on a full charge</li><li>Regenerative Braking System</li><li>MyFord Touch® 8\" Touchscreen with Navigation</li><li>Sony® Premium Audio System with 9 Speakers</li><li>Heated Leather-Trimmed Front Seats</li><li>Rearview Camera &amp; Reverse Sensing System</li><li>Keyless Entry with Push-Button Start</li><li>Dual-Zone Automatic Climate Control</li><li>SmartGauge™ with EcoGuide</li><li>SYNC® with Bluetooth Hands-Free Calling &amp; Voice Command</li><li>17\" Alloy Wheels</li><li>Automatic Headlights &amp; Rain-Sensing Wipers</li></ul><p>Charging &amp; Fuel Economy:</p><ul><li>Home Charging (Level 2): ~4–5 hours</li><li>Energy Consumption: 2.0 Le/100 km (combined)</li><li>Zero Emissions Driving</li></ul><p>Whether you\'re commuting downtown or running errands across town, the 2016 Ford Focus Electric Titanium offers a clean, quiet, and high-tech driving experience—without a drop of gas.</p><p>Contact us today to schedule your test drive and make the switch to electric driving!</p><p>✅ 2 years extended warranty included</p><p> ✅ Financing available for all kinds of credit</p><p><br></p>', 'available', 79800, 'km', 8995, '0', '5', '[\"Traction control\",\"Navigation system\",\"Bluetooth\",\"Power Seats\",\"Fully Loaded\",\"Leather seats\",\"Sunroof\",\"LED Headlight\",\"Bluetooth Audio\",\"Rearview Camera\",\"Multi-Function Steering Wheel\",\"Active Curise Control\",\"HEATED SEATS\",\"Remote start\"]', 2016, '[\"\\/storage\\/images\\/tACjWUNAt80q5DKgjCaWM9VWcnRBRFvcvqokb3IB.jpg\",\"\\/storage\\/images\\/qyzw6DdCtWgNV3eTReZFIUKbj1zTyuRB3J1UAbPy.jpg\",\"\\/storage\\/images\\/MwdhVX3uAFoBNd6eT2piv8zliOrJt8ZnCrWLDtTd.jpg\",\"\\/storage\\/images\\/qmRBFr74edg1EAr6VgCGbDsnXh22lGxb2pSUKEvg.jpg\",\"\\/storage\\/images\\/EyZTxS2IMb1vYprmo7vSSpbZOuyIA7JmHkIqDm7O.jpg\",\"\\/storage\\/images\\/zZb22X3ZxLDiUHPYCbe97hW2ynaBSxaB7sWEsbFI.jpg\",\"\\/storage\\/images\\/TX6kFnNh5Jjxa6IRqR1hHBKFckyZuD77yLYmNgK7.jpg\",\"\\/storage\\/images\\/f79KbjjDNO9SR90C73zZErJ5FcTNGarMXSpO3iiu.jpg\",\"\\/storage\\/images\\/kb6tRUFbEgsLycNX3bBJhZECZQbrYRLy88ivFvFO.jpg\",\"\\/storage\\/images\\/5iZomlFJmhB9woFdNfJO1d0TcXGnbqAjRpmpxCya.jpg\",\"\\/storage\\/images\\/C6BURtvPSW7lCzwXQ6deCkQvqvTby2AjePU0JUGH.jpg\",\"\\/storage\\/images\\/ASvRMSXeZjWHCse7mpjNDqvxqyL2e6RxreTv8Dao.jpg\",\"\\/storage\\/images\\/yhRThv5FAGA9SnZ0rTHUcf1hIMSpQEPvLpjyqaU0.jpg\",\"\\/storage\\/images\\/iVZyGbMiY4di1qaObEKt79nXEZLEXzQIoDZ6zjDV.jpg\",\"\\/storage\\/images\\/w7gDQdZ9VBpEGnxbc3cvbPuXdxyLQYhF4SkCaFPB.jpg\",\"\\/storage\\/images\\/Vj5NZEJHv26Nn7vuD9lD9IuqeQzMYXZmzOSjsPzT.jpg\",\"\\/storage\\/images\\/sgfIbiG8apKR9ofMF2rCMNGGSySpTfK29mIYXVnG.jpg\"]', 0, 0, 1, '2025-08-26 22:08:09', '2025-05-13 00:45:24', '2025-08-26 22:08:09', NULL, 'https://vhr.carfax.ca/?id=BUCVgidREY%2B%2B%2BkX3rysrA6AUFWj%2FzEYV', '1FADP3R4XGL291657', '0', '0'),
(249, '2018 JEEP GRAND CHEROKEE LIMITED', '2018-jeep-grand-cherokee-limited', 'Used', 'White', 'Black', 'Jeep', 'Automatic', 'Grand Cherokee', 'Suv', '4WD', '4', 'GAS', 'LIMITED', '<p><br></p><p>The 2018 Jeep Grand Cherokee Limited V6 is the perfect balance of rugged capability and upscale refinement. Powered by a 3.6L Pentastar V6 engine producing 295 horsepower and 260 lb-ft of torque, it delivers smooth performance on the highway and proven strength off the beaten path. With advanced 4x4 capability, a luxurious interior, and a host of tech and safety features, the Grand Cherokee Limited is built for those who demand both power and prestige.</p><p>Whether you\'re navigating city streets or exploring weekend trails, this SUV does it all—with style.</p><p>Key Features:</p><ul><li>3.6L Pentastar V6 Engine with 295 hp &amp; 260 lb-ft of torque</li><li>8-Speed Automatic Transmission</li><li>Jeep Quadra-Trac I 4x4 System</li><li>Leather-Trimmed Seats with Power Front Seats &amp; Driver Memory</li><li>Heated Front and Rear Seats + Heated Steering Wheel</li><li>Uconnect® 8.4\" Touchscreen with Navigation</li><li>Apple CarPlay® &amp; Android Auto™</li><li>Dual-Zone Automatic Climate Control</li><li>Power Liftgate</li><li>Remote Start System</li><li>Blind Spot Monitoring with Rear Cross-Path Detection</li><li>ParkView® Rear Back-Up Camera &amp; ParkSense® Rear Park Assist</li><li>Keyless Enter \'n Go™ with Push-Button Start</li><li>18\" Polished Aluminum Wheels</li><li>Roof Rails and Chrome Exterior Accents</li></ul><p>Fuel Economy:</p><ul><li>City: 12.7 L/100 km</li><li>Highway: 9.6 L/100 km</li><li>Combined: 11.3 L/100 km</li></ul><p>Whether you\'re after comfort, capability, or a little of both, the 2018 Jeep Grand Cherokee Limited V6 delivers a premium SUV experience that’s ready for any adventure.</p><p>Contact us today to book your test drive and experience luxury with legendary Jeep performance!</p><p>✅ 2 years extended warranty included</p><p> ✅ Financing available for all kinds of credit</p><p><br></p>', 'available', 158000, 'km', 20995, '3.6L', '5', '[\"Traction control\",\"Bluetooth\",\"Keyless Entry\",\"Power Seats\",\"Fully Loaded\",\"Leather seats\",\"Sunroof\",\"LED Headlight\",\"All Wheel Drive\",\"Bluetooth Audio\",\"Rearview Camera\",\"Towing Package\",\"Paddle Shift\",\"Multi-Function Steering Wheel\",\"Blind Spot Assist\",\"Keyless Go\",\"Power Tailgate\",\"Active Curise Control\",\"Bose Sound\",\"Heated steering\",\"Remote start\",\"HILL DESCENT\",\"HEATED SEATS\",\"Parking sensors\"]', 2018, '[\"\\/storage\\/images\\/VG1qlgWAwKtmtJmrp3vizqnN03MNfHXs1zVq00F6.jpg\",\"\\/storage\\/images\\/Mhe6yVsSdzyAZedbegb5WUdCQ1shZVe5lzCzGVtC.jpg\",\"\\/storage\\/images\\/RtwSlN4jloyp2aCSsBuG4YUTKHSqxOVni80PbSEZ.jpg\",\"\\/storage\\/images\\/xnx1O7pgLCWATQEuUVAP77wNEByZCAS3NlttqwGe.jpg\",\"\\/storage\\/images\\/Fc0kfliDRNDBECziRt9iLO101M8hXFYEduWbSCyY.jpg\",\"\\/storage\\/images\\/OX6zQDzsNkZ2fc41fm7p5JdcYUgWHePRgIpeYxM9.jpg\",\"\\/storage\\/images\\/xFF2POKA0xEuFVWjP20PB1tjel3mx0LOvrDyixXa.jpg\",\"\\/storage\\/images\\/JYQZg3Q92MYOrhpbA51k2EgsYW0PTBiYT8elaQZy.jpg\",\"\\/storage\\/images\\/PTmO1Oan44LYpk5pD16jZdBlcBQ3ncZbOCHhBpdP.jpg\",\"\\/storage\\/images\\/YoHVe3mRA0FyCqLjxyaZjdSSdozdbGoqpd6EXhyz.jpg\",\"\\/storage\\/images\\/gAwZD4ubZHuc9fYz3CbrcPOVJY1LvhqNzPIffvbB.jpg\",\"\\/storage\\/images\\/3Plq8FTTOnrk0hO8HDKpLxclAxu6ggNUbEmVOUUe.jpg\",\"\\/storage\\/images\\/NOx33N3SoeRLqXCiMgYreyUEbSqEPhKVYCyNcGhb.jpg\",\"\\/storage\\/images\\/Ls1qbQcdPDkz6Tjs5zT4KleirjFo2r3EUXxWksYZ.jpg\",\"\\/storage\\/images\\/GHa4hi1aKXOVuZKm9xdsGSY9GRK05fwgxBObwbdr.jpg\",\"\\/storage\\/images\\/p8Y3EaiX3m2edDeBY4Juv8JrIKYBaVSuAVA17ZlF.jpg\",\"\\/storage\\/images\\/ZP2InsXciJtOJJySf5hTIFOuy03Hh10ZuFHWoXtH.jpg\",\"\\/storage\\/images\\/QIvZHbEFJZrrJ6UwVwt7MISXvwF5dOli1orHRvqv.jpg\"]', 0, 1, 1, '2025-08-26 22:08:06', '2025-05-13 01:00:59', '2025-08-26 22:08:06', NULL, 'https://vhr.carfax.ca/?id=uKi3HX8i2Ml7NAkO8uIhLPWo8dV3PP20', '1C4RJFBG0JC134864', '12.7L', '9.6L'),
(250, '2018 MERCEDES BENZ CLA 250', '2018-mercedes-benz-cla-250', 'Used', 'White', 'Beige', 'Mercedes-Benz', 'Automatic', 'CLA-Class', 'Sedan', 'AWD', '4', 'GAS', 'Premium', '<p><br></p><p>The <strong>2018 Mercedes-Benz CLA 250 4MATIC Premium</strong> blends sporty coupe styling with refined luxury and all-weather confidence. Under the hood, a turbocharged 2.0L inline-4 engine delivers 208 horsepower and 258 lb-ft of torque, paired with a smooth 7-speed dual-clutch automatic transmission. With 4MATIC all-wheel drive and a sleek aerodynamic design, the CLA 250 offers agile performance and elevated comfort in a compact luxury package.</p><p>From its striking exterior to its tech-forward interior, this CLA is designed to turn heads and keep you connected.</p><p><strong>Key Features:</strong></p><ul><li>2.0L Turbocharged Inline-4 Engine with 208 hp &amp; 258 lb-ft of torque</li><li>7-Speed Dual-Clutch Automatic Transmission</li><li>4MATIC All-Wheel Drive System</li><li>Premium Package (Panoramic Sunroof, Keyless Go, Blind Spot Assist)</li><li>COMAND® 8\" Display with Navigation</li><li>Apple CarPlay® &amp; Android Auto™ Integration</li><li>Heated Power Front Seats with Memory</li><li>Dual-Zone Climate Control</li><li>Rearview Camera &amp; Active Brake Assist</li><li>Rain-Sensing Wipers &amp; Auto Headlights</li><li>Premium Leatherette Upholstery (ARTICO)</li><li>Attention Assist® Driver Monitoring</li><li>18\" AMG Twin 5-Spoke Alloy Wheels</li><li>LED High Performance Headlamps &amp; Taillamps</li></ul><p><strong>Fuel Economy:</strong></p><ul><li>City: 10.0 L/100 km</li><li>Highway: 7.2 L/100 km</li><li>Combined: 8.8 L/100 km</li></ul><p>With dynamic design, confident handling, and upscale amenities, the 2018 Mercedes-Benz CLA 250 Premium is perfect for drivers who want luxury and performance in a sleek, modern package.</p><p><strong>Contact us today to schedule your test drive and experience the bold elegance of the CLA!</strong></p><p>✅ <strong>2 years extended warranty included</strong></p><p> ✅ <strong>Financing available for all kinds of credit</strong></p><p><br></p>', 'sold', 148350, 'km', 16750, '2.0L', '5', '[\"Traction control\",\"Parking sensors\",\"Navigation system\",\"Bluetooth\",\"Keyless Entry\",\"Power Seats\",\"Fully Loaded\",\"Leather seats\",\"Panoramic Sunroof\",\"LED Headlight\",\"All Wheel Drive\",\"Bluetooth Audio\",\"Rearview Camera\",\"Upgraded Soft Leather\",\"Multi-Function Steering Wheel\",\"Paddle Shift\",\"Sport Seats\",\"Blind Spot Assist\",\"Keyless Go\",\"Power Seat with Memories\",\"AMG Sport Wheels\",\"Active Curise Control\",\"HEATED SEATS\"]', 2018, '[\"\\/storage\\/images\\/vG4u3ktOsWYMHRZCCV9ceXQji3oBmsuaSrC8Dlgx.jpg\",\"\\/storage\\/images\\/9xlF1y8ROhPXKJVzvAxOMpUwSb1ZPZk7F3ALETri.jpg\",\"\\/storage\\/images\\/ry7UxPfcTZZKfJmdXCmqsGi2bKNe1Ol8m8AOAcmW.jpg\",\"\\/storage\\/images\\/KVQewIPF1XQMW5tMzR9oHFt4gcIMY06TW1kKM6sG.jpg\",\"\\/storage\\/images\\/mwuI91uZJsbmTEeFkaTpb07C6gEOM4Jx6zwwSbRt.jpg\",\"\\/storage\\/images\\/G140mgfd5voiPfQyR1KplbEJKigNROJwqRmregTO.jpg\",\"\\/storage\\/images\\/qRtLqX3UBIE3o9T9TJs4rbxBTeOqEJdFe80CRhS8.jpg\",\"\\/storage\\/images\\/pI4QkjqpSc7qNGq8NoQSgmg2sod7spm5SGhXnYYy.jpg\",\"\\/storage\\/images\\/eC0EcDyXPAOZQ0AJPv71L7MFRGkrCKzEpN3Qy03j.jpg\",\"\\/storage\\/images\\/st50d8JSJqTqkFXnOpyIUlD8hfQ6keaSd0vHL9YB.jpg\",\"\\/storage\\/images\\/QsJNxx6S3zfrmpBp9W1S8t2HzmjW0F8a43BQEd6L.jpg\",\"\\/storage\\/images\\/t9UQt4HUJ2KxvyO0UC2EJaTnYqVdxMZvgkDhTt1G.jpg\",\"\\/storage\\/images\\/YL3DQKg5DZZUdkCMJEaqxnUSDAzJtuWIPp0fIYiB.jpg\",\"\\/storage\\/images\\/qVdV89ej32R3Vhf56B6AQOXcWlHKSu4eaktQGfVC.jpg\",\"\\/storage\\/images\\/VEcl3cTte0JzY5pghiSQ9sxXS7JP1SXBymhaAy8I.jpg\",\"\\/storage\\/images\\/wJM8MtywO6T787lBVbSVidkGNZ8RWvUYumi9hSyn.jpg\",\"\\/storage\\/images\\/RuAxPLS49acHGCb1dKjZz2E8bBknLfpBatXq8qAG.jpg\",\"\\/storage\\/images\\/MPqqx8F2pmkFigt7M8q3Wqm9gA2fErDIWpzJYwZF.jpg\",\"\\/storage\\/images\\/ZOGA0dNGkQgv7CQLvfpuAXaDRX67zVBPALrRtMyh.jpg\"]', 0, 0, 1, '2025-0