INSERT INTO `contacts` (`id`, `name`, `email`, `subject`, `message`, `phone`, `created_at`, `updated_at`) VALUES
(1, 'Matiullah Karimi', 'matiullah.karimi@gmail.com', 'Testing email', 'Salam Emad jan,\n\nPlease confirm if you receive my email', NULL, '2024-06-24 03:29:48', '2024-06-24 03:29:48'),
(2, 'Dominic S DSouza', 'dominicsdsouza@gmail.com', 'Car Dealership Manager', 'My name is Dominic DSouza. I am looking to apply as a Car Dealership Manager.   I have been in the automotive Industry since 1987. In all of the department, as a Technical Instructor (training apprentices & adult training mechanics), General shop foreman (auto mechanics, fork lifts, body and paint shop), Sr. Service advisor, ( Awards received from Toyota Canada, National advisory skills in 2002. Honda Canada, Platinum Service Advisor in 2012)\n\n\nCompleted my Diploma of associate engineering in Automotive and Diesel Technology in the year 1988. Completed online courses and in-class Service Advisor training with Toyota Canada, Toyota Education Mastery Program, Toyota Motor Corporation, 1992. Online and in class courses with Honda Canada as well. I had my O.M.V.I.C license.\n\nLooking to join your team as a Car Dealership Manager.\n\nPlease Find attached my resume.\n\nThanks & Regards\n\nDominic S Dsouza.\n\nCell # 647-703-4445', NULL, '2024-07-03 00:29:59', '2024-07-03 00:29:59'),
(3, 'Robert Bacchus', 'robert.r.bacchus@gmail.com', 'Inquiry About Marketing Opportunities with Xtreme Motors Inc', 'Dear Xtreme Motors Hiring Team,\n\nI hope this email finds you well. I am writing to express my interest in potential marketing opportunities with Xtreme Motors. I have extensive experience in marketing, with a particular focus on digital marketing strategies, including search engine optimization (SEO), content marketing, and PPC advertising.\n\nThank you for considering my inquiry. I look forward to the possibility of contributing to Xtreme Motors\' success.\n\nWarm regards,\nRobert Bacchus\nRobert.r.bacchus@gmail.com\nAdvanced Diploma: Business Administration - Marketing\nBaccalaureate Degree: Honours Bachelor of Business Administration (Marketing Management)\nUndergraduate Certificate: Creativity and Creative Problem Solving', NULL, '2024-09-11 04:09:44', '2024-09-11 04:09:44'),
(4, 'Kulesudaice', 'kulesudaice@gmail.com', 'Application to work with you', 'I am a 24 year old car dealer in East Africa and I have always seen potential in a reputable company like yours,if given chance I would like to be part of your car dealers team and if possible to expand market to east Africa to drive more sales to company,I love progress of your company and I would entirely love to be part of team', NULL, '2024-10-15 03:26:01', '2024-10-15 03:26:01'),
(5, 'Dominic D\'Souza', 'dominicsdsouza@gmail.com', 'Car Dealership Manager', 'I have seen an advertisement on Indeed for a Car Dealership Manager, I would like to apply for the same. \nI have been in the automotive service department for about about 35 Years in all Departments,  I am looking for a part time job at your store. \nI can speak about 5 languages, I live in Brampton. (Sandalwood & Kennedy). \nPlease let me know if you are looking for someone like me. I can send you my resume..\n\nLooking forward to hearing from you.\n\nBest Regards.\n\nDominic D\'souza', NULL, '2024-10-31 00:35:47', '2024-10-31 00:35:47'),
(6, 'Dominic', 'dominicsdsouza@gmail.com', 'Car Dealership Manager', 'I have seen an advertisement on Indeed for a Car Dealership Manager, I would like to apply for the same. \nI have been in the automotive service department for a very long time, \nI can speak about 5 languages, I live in Brampton. (Sandalwood & Kennedy). \nPlease let me know I can send you my resume.\n\nLooking forward to hearing from you.\n\nBest Regards.\n\nDominic D\'souza', NULL, '2024-11-07 21:34:11', '2024-11-07 21:34:11'),
(7, 'Dominic', 'dominicsdsouza@gmail.com', 'Car Dealership Manager', 'Hello.\nHaving seen an advertisement on Indeed for a Car Dealership Manager, I would like to apply for the same. \nI have been in the automotive service department for a very long time,  I am looking for a job at your store. \nI can speak about 5 languages, I live in Brampton. (Sandalwood & Kennedy). \nPlease let me know I can send you my resume.\nLooking forward to hearing from you.\nBest Regards.\nDominic D\'souza', NULL, '2024-11-13 03:46:38', '2024-11-13 03:46:38'),
(8, 'KAMAL SATEA ALJENDI', 'DALF-est@hotmail.com', 'Looking for a help to get any job offer through Regional EMPP Program ( without need to LMIA ) – ( without any other responsibilities or results )', 'Hello,\nI am Kamal Satea Aljendi\nI am Syrian Refugee living ( with my family ) in Saudi Arabia\nI and my family are acceptable in UNHCR – Division of International Protection ( DIP ) on ( Apr 23, 2020 ) \n\nI have a profile in Talent Lift Canada\nI have a profile in Talent Beyond Boundaries – Canada \nMy Account (TBB-210454) in Talent Beyond Boundaries – Canada\nAfter my getting any job offer, then Talent Lift Canada ( OR ) Talent Beyond Boundaries – Canada will start the official procedures for my coming to Canada ( with my family ) through Regional ( EMPP ) Program ( without need to LMIA ) \nMay you help me in this regard \n\nBest regards,', NULL, '2024-11-29 08:21:07', '2024-11-29 08:21:07'),
(9, 'Daniel Zhang', 'sales05@48log.com', 'Freight forwarding service', 'This is Daniel from Fourever International Limited. Wish you have a good day！:)\n \nAllow me to introduce Fourever International Limited (48LOG), a leading logistics provider headquartered in Shenzhen, China. Our core expertise lies in ocean and air shipping, complemented by a full suite of services including LCL, warehousing, delivery, and customs clearance – both in the China and the USA. Moreover, we extend our reach globally to Europe, the Middle East, Southeast Asia, and Latin America, catering to your every shipping need.\n\nSincerely hope we can have a chance to make cooperation with you.If you have any need of our services, please kindly contact me, we will take the best plan to meet your request.\n\nDaniel Zhang\nFourever International Limited\nsales05@48log.com\nWhatsAPP: +86 13928400946', NULL, '2024-11-29 09:19:45', '2024-11-29 09:19:45'),
(10, 'SADIK', 'abdelmounaim125@gmail.com', 'Car dealership manager', 'Dear Sir/Madam,\n\nI hope this message finds you well. I came across your job offer for the manager position, and I am very interested in applying. As someone with a passion for leadership and a deep appreciation for cars, I would be truly honored to join your team. I am confident that my skills and enthusiasm align well with the requirements of this role.\nI look forward to the opportunity to contribute to your organization and hope to hear from you soon.\n\nBest regards\nsadik.', NULL, '2024-12-02 18:29:46', '2024-12-02 18:29:46'),
(11, 'Alex', 'dniproshina@gmail.com', 'Sent you my CV', 'Hi, team. Just sent you my CV on your mailbox, check it please. Alex', NULL, '2024-12-11 00:56:12', '2024-12-11 00:56:12'),
(12, 'Clint', 'clint108web@gmail.com', '2017 GMC Sierra SLT all terrain pickup', 'Hey, I\'m wondering about your 2017 GMC pickup....did the previous owners smoke in it or have any accidents with it? Also is it a 1 owner pickup? We might want to come look at it...it looks sharp.', NULL, '2025-04-08 22:50:20', '2025-04-08 22:50:20'),
(13, 'Susan White', 'susan@wikiexpertiinc.com', 'Get A Wikipedia Page For Yourself Or For Your Company.', 'Wikipedia is considered to be the World’s most significant tool for reference material. The Wiki links show up on the 1st page of Google 97% of the time. With a Page on one of the most revered reference tools, you are sure to get yourself or your business noticed. So if you\'re thinking of getting a Wikipedia Page created, it\'s the best time of the year.\n\nIf you are interested in getting more information just respond back to this email.\n\nThanks,\n\nSusan White\nWiki Experts Inc\nsusan@wikiexpertiinc.com\n\nRespond with stop to optout.', NULL, '2025-06-26 15:15:17', '2025-06-26 15:15:17'),
(14, 'Sarah Balazsy', 'sarahveld99@gmail.com', 'GMC Sierra', 'Good afternoon, me and my husband purchased a 2017 GMC Sierra 1500 crew cab from you guys back in May of last year, I can’t seem to find the receipt for it I’m just wondering if you’d be able to email me a copy of it? My husbands name is Stephen Balazsy', NULL, '2026-03-30 23:30:15', '2026-03-30 23:30:15');
